let colors1 = ['#083d77', '#da4167', '#f4d35e', '#01baef', '#048a81'];
let colors2 = ['#083d77', '#da4167', '#f4d35e', '#01baef', '#048a81', '#1C1B19', '#fdfaf8'];

let ctx;
let centerX, centerY;
let shapes = [];
let canSpawn = true;
let shapeMargin = 5;

function setup() {
	createCanvas(700, 875);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
