function draw() {
  // === Variant 3: Fractal Orbit Matrix ===
  gridOffset = noise(frameCount * 0.01) * 80;
  push();
  translate(gridOffset, -gridOffset);

	canSpawn = true;
	background('#e3e3e3');

	for (let i of shapes) {
		i.run();
	}
	for (let i = 0; i < shapes.length; i++) {
		let s = shapes[i];
		if (s.isDead) {
			shapes.splice(i, 1);
		}
	}
	for (let i = 0; i < shapes.length; i++) {
		let s = shapes[i];
		if ((s.currentY - (s.h / 2) + s.velocityY) < 0) {
			canSpawn = false;
			break;
		}
	}
	if (canSpawn) {
		divideRect(width / 2, -height / 2, width - shapeMargin * 2, height - shapeMargin * 2);
	}

  pop();
}

function divideRect(x, y, w, h) {
	let ww = random(0.15, 0.85) * w;
	let hh = random(0.15, 0.85) * h;
	let xx = x - (w / 2) + ww;
	let yy = y - (h / 2) + hh;
	let minSize = width * 0.1;

	if (minSize < w && minSize < h) {
		if (h < w) {
			divideRect(xx - ww / 2, y, ww, h);
			divideRect(xx + (w - ww) / 2, y, (w - ww), h);
		} else {
			divideRect(x, yy - hh / 2, w, hh);
			divideRect(x, yy + (h - hh) / 2, w, h - hh);
		}
	} else {
		shapes.push(new Shape(x, y, w - shapeMargin, h - shapeMargin));
	}
}

function easeInOutQuart(x) {
	return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
}


class Shape {
	constructor(x, y, w, h) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.currentX = x;
		this.currentY = y;
		this.direction = random([PI, 0, PI * 1.5, PI * 1.5]);
		let r = width * 1.1;
		this.shiftX = r * cos(this.direction);
		this.shiftY = r * sin(this.direction);
		this.shiftX0 = this.shiftX;
		this.shiftY0 = this.shiftY;
		this.shiftX1 = 0;
		this.shiftY1 = 0;
		this.velocityY = height / 500;
		this.timer = 0;
		this.phase1 = 180;
		this.border = height * random(0.2);
		this.isDead = false;
		this.scaleX = 1;
		this.scaleY = 1;
		this.clr = random(colors1);
		this.clr1 = random(colors2);
		this.clr2 = random(colors2);
		while (this.clr1 == this.clr2) {
			this.clr1 = random(colors2);
			this.clr2 = random(colors2);
		}

		this.shapeType = random([0, 0, 1, 2, 0, 0]);
		this.corner = width * 0.008;
		this.separation = int(random(10, 14));
	}

	show() {
		push();
		translate(this.currentX, this.currentY);
		scale(this.scaleX, this.scaleY);
		noStroke();

		if (this.shapeType == 0) {
			fill(this.clr);
			rect(this.shiftX, this.shiftY, this.w, this.h, this.corner);
		} else {
			fill('#fff');
			fill(this.clr1);
			strokeWeight(0);
			rect(this.shiftX, this.shiftY, this.w, this.h, this.corner);
			ctx.clip();
			this.checkered();
		}

		pop();
	}

	checkered() {
		let c = this.separation;
		let side = max(this.w, this.h);
		let w = side / c;
		for (let i = 0; i < c; i++) {
			for (let j = 0; j < c; j++) {
				let x = i * w + (w / 2) - (this.w / 2) + this.shiftX + (this.w - side) / 2;
				let y = j * w + (w / 2) - (this.h / 2) + this.shiftY + (this.h - side) / 2;
				if ((i + j) % 2 == 0) {
					fill(this.clr2);
					if (this.shapeType == 1) circle(x, y, w);
					else if (this.shapeType == 2) square(x, y, w);
				}
			}
		}
	}

	update() {
		this.currentY += this.velocityY
		if (this.currentY > this.border) {
			if (0 < this.timer && this.timer < this.phase1) {
				let nrm = norm(this.timer, 0, this.phase1 - 1);
				let ease = easeInOutQuart(nrm);
				this.shiftX = lerp(this.shiftX0, this.shiftX1, ease);
				this.shiftY = lerp(this.shiftY0, this.shiftY1, ease);

				if (this.direction == 0 || this.direction == PI) {
					this.scaleX = lerp(1, 2, sin(ease * PI));
					this.scaleY = lerp(1, 0, sin(ease * PI));
				} else {
					this.scaleY = lerp(1, 2, sin(ease * PI));
					this.scaleX = lerp(1, 0, sin(ease * PI));
				}
			}
			this.timer++;
		}

		if ((this.currentY - (this.h / 2)) > height) {
			this.isDead = true;
		}
	}

	run() {
		this.show();
		this.update();
	}
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
